import (
	"sort"
	"testing"
)

// normalize sorts each component and then the components, so a solution is
// free to emit them in any order.
func normalize(comps [][]int) [][]int {
	out := make([][]int, 0, len(comps))
	for _, c := range comps {
		c = append([]int(nil), c...)
		sort.Ints(c)
		out = append(out, c)
	}
	sort.Slice(out, func(i, j int) bool { return out[i][0] < out[j][0] })
	return out
}

func equal(got, want [][]int) bool {
	if len(got) != len(want) {
		return false
	}
	for i := range got {
		if len(got[i]) != len(want[i]) {
			return false
		}
		for j := range got[i] {
			if got[i][j] != want[i][j] {
				return false
			}
		}
	}
	return true
}

