// TestSCCLargeChainOfCyclesIsLinear builds 40000 five-node cycles chained
// forward. Deciding mutual reachability with a search from every node is
// O(n*m) and does not finish.
func TestSCCLargeChainOfCyclesIsLinear(t *testing.T) {
	const groups = 60000
	const n = groups * 5
	edges := make([][]int, 0, n+groups)
	for g := 0; g < groups; g++ {
		base := g * 5
		for i := 0; i < 5; i++ {
			edges = append(edges, []int{base + i, base + (i+1)%5})
		}
		if g+1 < groups {
			edges = append(edges, []int{base + 2, base + 5})
		}
	}
	comps := stronglyConnectedComponents(n, edges)
	if len(comps) != groups {
		t.Fatalf("got %d components, want %d", len(comps), groups)
	}
	seen := make([]bool, groups)
	for _, c := range comps {
		if len(c) != 5 {
			t.Fatalf("component %v has %d nodes, want 5", c, len(c))
		}
		g := c[0] / 5
		for _, v := range c {
			if v/5 != g {
				t.Fatalf("component %v mixes cycle %d and cycle %d", c, g, v/5)
			}
		}
		if seen[g] {
			t.Fatalf("cycle %d reported twice", g)
		}
		seen[g] = true
	}
}

